package codegen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"strconv"
	"strings"

	"github.com/reliant-labs/forge/internal/changesdecl"
	"github.com/reliant-labs/forge/pkg/release"
)

// ChangesGoFile is the generated Go accessors' path, relative to the project
// root.
const ChangesGoFile = "internal/changes/changes_gen.go"

// ChangesTSFile is the generated TypeScript accessors' path inside a
// frontend, relative to the frontend root.
const ChangesTSFile = "src/lib/changes_gen.ts"

// changesHeader opens both generated files: what they are, and where to edit.
func changesHeader(comment string) string {
	return comment + " Code generated by forge. DO NOT EDIT.\n" +
		comment + " forge-owned: regenerated every run — do not edit (forge project disown to take ownership)\n" +
		comment + " Source: " + changesdecl.FileName + " — the project's declared Forge Changes. Edit that file and run\n" +
		comment + " `forge generate`; deleting it deletes this file.\n"
}

// GenerateChangesGo renders internal/changes/changes_gen.go: one constant
// and one typed accessor per declared change, over pkg/changes' Store. The
// accessor's literal default is the declared default variant's value, so a
// snapshot that does not carry the change (none delivered yet, or a key the
// platform has never seen) still yields the declared behavior.
//
// Each change is its own forge:section, after a preamble that does not depend
// on which changes exist (the imports are the same for every type), so two
// branches that change different changes merge with plain git.
func GenerateChangesGo(d *changesdecl.Decl) ([]byte, error) {
	var b strings.Builder
	b.WriteString(changesHeader("//"))
	b.WriteString(`
// Package changes is a typed accessor for each change ` + changesdecl.FileName + ` declares. Open
// one store per process and pass it to each accessor:
//
//	store := changes.OpenFile(ctx, os.Getenv(changes.EnvFile), changes.Options{})
//	defer store.Close()
//	if appchanges.NewCheckout(ctx, store, changes.EvalContext{TargetingKey: userID}) { ... }
//
// (with pkg/changes imported as changes and this package as appchanges). An
// accessor never fails: a change the snapshot does not carry, or a store with
// no snapshot, yields the declared default.
package changes

import (
	"context"

	"github.com/reliant-labs/forge/pkg/changes"
)

`)
	for _, c := range d.Changes {
		name := changesdecl.GoName(c.Key)
		fmt.Fprintf(&b, "// forge:section %s\n", c.Key)
		fmt.Fprintf(&b, "\n// Key%s is the key of the change %s evaluates.\nconst Key%s = %q\n\n", name, name, name, c.Key)
		writeGoDoc(&b, name, c)
		def := c.DefaultValue()
		switch c.Type {
		case release.ChangeTypeBool:
			fmt.Fprintf(&b, "func %s(ctx context.Context, s *changes.Store, ec changes.EvalContext) bool {\n\treturn changes.Bool(s.Evaluate(ctx, Key%s, ec), %s)\n}\n", name, name, def)
		case release.ChangeTypeString:
			fmt.Fprintf(&b, "func %s(ctx context.Context, s *changes.Store, ec changes.EvalContext) string {\n\treturn changes.String(s.Evaluate(ctx, Key%s, ec), %s)\n}\n", name, name, strconv.Quote(jsonString(def)))
		case release.ChangeTypeNumber:
			lit, err := numberLiteral(def)
			if err != nil {
				return nil, fmt.Errorf("change %q: default: %w", c.Key, err)
			}
			fmt.Fprintf(&b, "func %s(ctx context.Context, s *changes.Store, ec changes.EvalContext) float64 {\n\treturn changes.Float64(s.Evaluate(ctx, Key%s, ec), %s)\n}\n", name, name, lit)
		case release.ChangeTypeJSON:
			fmt.Fprintf(&b, "func %s(ctx context.Context, s *changes.Store, ec changes.EvalContext, v any) bool {\n"+
				"\tif changes.Decode(s.Evaluate(ctx, Key%s, ec), v) {\n\t\treturn true\n\t}\n"+
				"\t_ = changes.Decode(changes.Result{Value: []byte(%s)}, v)\n\treturn false\n}\n", name, name, goStringLiteral(string(def)))
		default:
			return nil, fmt.Errorf("change %q: unknown type %q", c.Key, c.Type)
		}
		b.WriteString("\n")
	}
	out, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("format %s: %w", ChangesGoFile, err)
	}
	return out, nil
}

// writeGoDoc writes an accessor's doc comment: the description, then what
// the change is and what the accessor returns.
func writeGoDoc(b *strings.Builder, name string, c changesdecl.Change) {
	fmt.Fprintf(b, "// %s evaluates the change %q", name, c.Key)
	if c.Description != "" {
		b.WriteString(":\n")
		for _, line := range strings.Split(strings.TrimSpace(c.Description), "\n") {
			b.WriteString(strings.TrimRight("// "+line, " ") + "\n")
		}
	} else {
		b.WriteString(".\n")
	}
	fmt.Fprintf(b, "//\n// A %s change with variants %s.\n", c.Type, describeVariants(c))
	switch c.Type {
	case release.ChangeTypeJSON:
		b.WriteString("// It decodes the chosen variant's value into v, a pointer as for json.Unmarshal,\n" +
			"// and reports true; when the snapshot does not decide, it decodes the declared\n" +
			"// default into v and reports false.\n")
	default:
		b.WriteString("// When the snapshot does not decide, it returns the declared default.\n")
	}
}

// GenerateChangesTS renders a frontend's src/lib/changes_gen.ts: a key
// constant and a typed accessor per declared change, over
// @reliantlabs/forge-web-runtime's ChangesStore, with the declared default
// variant's value as its default. Like the Go file, each change is its own
// forge:section after a preamble that does not depend on which changes exist:
// the runtime is imported as one namespace, so a change of a new type adds no
// import line two branches could both edit.
func GenerateChangesTS(d *changesdecl.Decl) ([]byte, error) {
	var b strings.Builder
	b.WriteString(changesHeader("//"))
	b.WriteString(`//
// One typed accessor per change. Load the store once per page and pass it in:
//
//   const store = await loadChanges();
//   if (newCheckout(store, { targetingKey: userId })) { ... }
//
// An accessor never throws: a change the snapshot does not carry, or a store
// that could not load, yields the declared default.

import * as forge from "@reliantlabs/forge-web-runtime";

`)
	for _, c := range d.Changes {
		name := changesdecl.TSName(c.Key)
		fmt.Fprintf(&b, "// forge:section %s\n\n", c.Key)
		decl := fmt.Sprintf("export const %sKey = %s;", name, jsString(c.Key))
		if len(decl) > 100 {
			decl = fmt.Sprintf("export const %sKey =\n  %s;", name, jsString(c.Key))
		}
		fmt.Fprintf(&b, "/** The key of the change `%s`. */\n%s\n\n", c.Key, decl)
		writeTSDoc(&b, c)
		def := c.DefaultValue()
		var ret, body, generic string
		switch c.Type {
		case release.ChangeTypeBool:
			ret, body = "boolean", fmt.Sprintf("forge.changeBool(r, %s)", def)
		case release.ChangeTypeString:
			ret, body = "string", fmt.Sprintf("forge.changeString(r, %s)", jsString(jsonString(def)))
		case release.ChangeTypeNumber:
			lit, err := numberLiteral(def)
			if err != nil {
				return nil, fmt.Errorf("change %q: default: %w", c.Key, err)
			}
			ret, body = "number", fmt.Sprintf("forge.changeNumber(r, %s)", lit)
		case release.ChangeTypeJSON:
			generic = "<T = unknown>"
			ret, body = "T", fmt.Sprintf("forge.changeJson<T>(r, JSON.parse(%s) as T)", jsString(string(def)))
		default:
			return nil, fmt.Errorf("change %q: unknown type %q", c.Key, c.Type)
		}
		sig := fmt.Sprintf("export function %s%s(store: forge.ChangesStore, ctx?: forge.ChangeEvalContext): %s {", name, generic, ret)
		if len(sig) > 100 {
			sig = fmt.Sprintf("export function %s%s(\n  store: forge.ChangesStore,\n  ctx?: forge.ChangeEvalContext,\n): %s {", name, generic, ret)
		}
		ret2 := "  return " + body + ";"
		if len(ret2) > 100 {
			ret2 = "  return " + strings.Replace(body, "(r, ", "(\n    r,\n    ", 1)
			ret2 = strings.TrimSuffix(ret2, ")") + ",\n  );"
		}
		fmt.Fprintf(&b, "%s\n  const r = store.evaluate(%sKey, ctx);\n%s\n}\n\n", sig, name, ret2)
	}
	return []byte(strings.TrimSuffix(b.String(), "\n")), nil
}

func writeTSDoc(b *strings.Builder, c changesdecl.Change) {
	b.WriteString("/**\n")
	if c.Description != "" {
		for _, line := range strings.Split(strings.TrimSpace(c.Description), "\n") {
			b.WriteString(strings.TrimRight(" * "+strings.ReplaceAll(line, "*/", "*\\/"), " ") + "\n")
		}
		b.WriteString(" *\n")
	}
	fmt.Fprintf(b, " * The change `%s`: a %s with variants %s.\n", c.Key, c.Type, describeVariants(c))
	b.WriteString(" * When the snapshot does not decide, it returns the declared default.\n */\n")
}

// describeVariants lists a change's variants for a doc comment, in file
// order, marking the default: "control (false, the default) and treatment
// (true)". A value too long to read inline is left out.
func describeVariants(c changesdecl.Change) string {
	parts := make([]string, 0, len(c.Variants))
	for _, v := range c.Variants {
		var notes []string
		if len(v.Value) <= 40 {
			notes = append(notes, strings.ReplaceAll(string(v.Value), "*/", "*\\/"))
		}
		if v.Name == c.Default {
			notes = append(notes, "the default")
		}
		p := v.Name
		if len(notes) > 0 {
			p += " (" + strings.Join(notes, ", ") + ")"
		}
		parts = append(parts, p)
	}
	switch len(parts) {
	case 1:
		return parts[0]
	default:
		return strings.Join(parts[:len(parts)-1], ", ") + " and " + parts[len(parts)-1]
	}
}

// numberLiteral is a JSON number as a literal both Go (an untyped float
// constant) and TypeScript read as the same float64.
func numberLiteral(raw json.RawMessage) (string, error) {
	f, err := strconv.ParseFloat(string(bytes.TrimSpace(raw)), 64)
	if err != nil {
		return "", err
	}
	return strconv.FormatFloat(f, 'g', -1, 64), nil
}

func jsonString(raw json.RawMessage) string {
	var s string
	_ = json.Unmarshal(raw, &s)
	return s
}

// goStringLiteral quotes s as a raw string when it can, so a JSON default
// stays readable, and as an interpreted one when it holds a backquote.
func goStringLiteral(s string) string {
	if !strings.Contains(s, "`") {
		return "`" + s + "`"
	}
	return strconv.Quote(s)
}

// jsString quotes s as a JavaScript string literal the way prettier would:
// double quotes, unless single quotes need fewer escapes.
func jsString(s string) string {
	var buf bytes.Buffer
	e := json.NewEncoder(&buf)
	e.SetEscapeHTML(false)
	_ = e.Encode(s) // still escapes U+2028/U+2029 and every control character
	lit := strings.TrimSuffix(buf.String(), "\n")
	if strings.Count(s, `"`) <= strings.Count(s, `'`) {
		return lit
	}
	inner := strings.ReplaceAll(lit[1:len(lit)-1], `\"`, `"`)
	return "'" + strings.ReplaceAll(inner, `'`, `\'`) + "'"
}
